            .toSet();
        final petDeclared = method
            .allMatches(petSource.substring(petSplit))
            .map((m) => m.group(1)!)
            .toSet();
        expect(petDeclared, petListed);
        final problemsSource = File(
          'lib/src/api/problems_api.dart',
        ).readAsStringSync();
        final problemsSplit = problemsSource.indexOf(
          'class ProblemsApi extends BaseApi',
        );
        final problemsListed = method
            .allMatches(problemsSource.substring(0, problemsSplit))
            .map((m) => m.group(1)!)
            .toSet();
        final problemsDeclared = method
            .allMatches(problemsSource.substring(problemsSplit))
            .map((m) => m.group(1)!)
            .toSet();
        expect(problemsDeclared, problemsListed);
        final storeSource = File(
          'lib/src/api/store_api.dart',
        ).readAsStringSync();
        final storeSplit = storeSource.indexOf(
          'class StoreApi extends BaseApi',
        );
        final storeListed = method
            .allMatches(storeSource.substring(0, storeSplit))
            .map((m) => m.group(1)!)
            .toSet();
        final storeDeclared = method
            .allMatches(storeSource.substring(storeSplit))
            .map((m) => m.group(1)!)
            .toSet();
        expect(storeDeclared, storeListed);
      },
    );

    test(
      'bhv mocking 007 the client interface exposes every group typed as its interface and close',
      () {
        final client = Client(authenticator: authenticator);
        final viaInterface = client as ClientInterface;

        final petGroup = viaInterface.pet;
        expect(petGroup, same(client.pet));
        final problemsGroup = viaInterface.problems;
        expect(problemsGroup, same(client.problems));
        final storeGroup = viaInterface.store;
        expect(storeGroup, same(client.store));
        expect(() {
          viaInterface.close();
          viaInterface.close();
        }, returnsNormally);
      },
    );

    test(
      'bhv mocking 008 a client built from fakes never connects and closes without error',
      () {
        final fake = _FakeClient();
        final viaInterface = fake as ClientInterface;

        expect(viaInterface.pet, isNotNull);
        expect(viaInterface.problems, isNotNull);
        expect(viaInterface.store, isNotNull);
        viaInterface.close();
        viaInterface.close();

        expect(fake.closed, 2);
      },
    );

    test(
      'bhv hooks 010 a hook given to the client fires for an operation when the caller supplied the transport',
      () async {
        final hook = _CountingHook();
        final client = Client(
          authenticator: BearerAuthenticator(
            host: 'https://api.example.com',
            token: 'test-token',
          ),
          transportOptions: TransportOptionsBuilder()
              .httpClient(
                MockClient(
                  (_) async => http.Response(
                    '{"name":"a","photoUrls":[]}',
                    200,
                    headers: {'content-type': 'application/json'},
                  ),
                ),
              )
              .build(),
          callHook: hook,
        );

        await client.pet.getPetById(1, null, null);

        expect(hook.starts, equals(1));
        expect(hook.finishes, equals(1));
      },
    );

    test(
      'bhv langdart 028 the client hands the call hook to every API group',
      () async {
        final hook = _CountingHook();
        final client = Client.withToken(
          host: 'https://api.example.com',
          accessToken: 'test-token',
          transportOptions: TransportOptionsBuilder()
              .httpClient(MockClient((_) async => http.Response('{}', 404)))
              .build(),
          callHook: hook,
        );

        expect(client.pet.config.callHook, same(hook));
        expect(client.problems.config.callHook, same(hook));
        expect(client.store.config.callHook, same(hook));
      },
    );
  });
}

class _TransportRecordingBearer extends BearerAuthenticator
    implements HttpAwareAuthenticator {
  _TransportRecordingBearer({required super.host, required super.token});

  ApiClient? injected;

  @override
  void setApiClient(ApiClient client) {
    injected = client;
  }
}

class _CountingHook implements CallHook {
  int starts = 0;
  int finishes = 0;

  @override
  CallObserver? start(CallInfo info, Map<String, String> headers) {
    starts++;
    return _CountingObserver(this);
  }
}

class _CountingObserver implements CallObserver {
  _CountingObserver(this._hook);

  final _CountingHook _hook;

  @override
  void finish(CallOutcome outcome) {
    _hook.finishes++;
  }
}
